const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'src', 'data', 'lessons');

// Platformer voice: Cherno — visual, debugger-friendly, 2D physics focused

const lessons = [
  // === BT, EI, ST (all three needed) ===
  { file: 'lesson-platformer-07-air-control.ts',
    bt: '**Applying the same acceleration in the air as on the ground.** Air control should feel lighter — use a reduced acceleration multiplier (0.3-0.5x ground speed). Full ground acceleration in midair makes the character feel like it is ice-skating through the sky.',
    ei: 'Celeste uses different air-control curves depending on whether the player is rising or falling. The ascending arc has less horizontal control than the descending arc, which makes jumps feel committed but landings feel responsive.',
    st: 'The Shooter does not have air control — ships move freely in all directions. The RPG moves on a grid with no jump. Your air dampening factor is unique to platformers, but the concept of context-dependent movement speed appears in every genre.' },
  { file: 'lesson-platformer-08-coyote-time.ts',
    bt: '**Starting the coyote timer when the player presses jump instead of when they leave the ground.** Coyote time is the grace period AFTER leaving a ledge where a jump is still allowed. If you start it on jump press, you have implemented a jump buffer instead.',
    ei: 'The term "coyote time" comes from Wile E. Coyote running off cliffs and not falling immediately. Celeste, Hollow Knight, and nearly every modern platformer grants 6-10 frames of coyote time. Players perceive it as "the game is fair" rather than noticing the mechanic.',
    st: 'The RPG path has no jump mechanic — movement is grid-based. The Shooter has no gravity. But input forgiveness is universal: the RPG queues movement commands, and the Shooter buffers rapid-fire input. Every path forgives imprecise timing in its own way.' },
  { file: 'lesson-platformer-09-jump-buffer.ts',
    bt: '**Making the jump buffer last forever.** If the player presses jump 2 seconds before landing, they probably changed their mind. A 6-10 frame buffer (100-170ms) captures intentional early presses without creating ghost jumps long after the input.',
    ei: 'Hollow Knight stacks coyote time and jump buffering together — you can run off a ledge and press jump slightly late (coyote) or press jump slightly early before landing (buffer). The combination makes every jump feel perfectly responsive.',
    st: 'The RPG queues the next move command while the current move animates — that is a command buffer. The Shooter buffers fire input between cooldowns. Input buffering is a universal UX pattern: absorb early input and apply it at the correct moment.' },
  { file: 'lesson-platformer-10-milestone-micro-platformer.ts',
    bt: '**Adding new mechanics before the core loop (move, jump, land, collide) works perfectly.** Wall jumps do not fix a broken ground collision. Verify the minimal platformer end-to-end before layering complexity.',
    ei: 'Super Mario Bros shipped with only run and jump. Mega Man added shooting. Celeste added dash. Every great platformer starts with a tight core loop and layers mechanics on top. Your milestone proves the core is solid.',
    st: 'Every path hits this milestone — RPG L10, Shooter L10, Crawler L10. The core loop test is universal: prove the minimal viable game works before building on it. The genre changes, the milestone principle does not.' },
  { file: 'lesson-platformer-11-tile-grid-data.ts',
    bt: '**Storing tile data as a 2D array of strings instead of integers.** String comparison is slow and error-prone ("wall" vs "Wall" vs "WALL"). Use integer constants or an enum: 0 = empty, 1 = solid, 2 = coin. Integer lookup is O(1) with no string overhead.',
    ei: 'Tiled, the most popular 2D level editor, stores maps as integer grids with a separate tileset definition. Every tile ID is a number that indexes into the tileset. Your grid[y][x] integer approach matches the industry-standard format.',
    st: 'The RPG stores dungeon rooms as integer grids the same way — 0 for floor, 1 for wall, 2 for door. The Crawler stores 3D voxel data as integers. Grid-based level data with integer tile IDs is the universal level representation across all paths.' },
  { file: 'lesson-platformer-12-grid-collision-v0.ts',
    bt: '**Checking collision against every tile in the grid.** If your grid is 40x30, that is 1200 checks per entity per frame. Only check the tiles the entity overlaps — convert the entity bounding box to grid coordinates and check those 2-4 tiles.',
    ei: 'AABB-to-grid collision is the foundation of every tile-based platformer from Super Mario to Celeste. Convert pixel position to grid index, check the tile type, resolve the overlap. The entire algorithm is four integer divisions and four array lookups.',
    st: 'The RPG uses direct grid lookup (grid[y][x]) for wall collision. The Shooter uses spatial grids for entity-entity collision. Your tile-grid AABB check is the platformer-specific version — same O(1) grid lookup, applied to continuous-space movement.' },
  { file: 'lesson-platformer-13-horizontal-collision.ts',
    bt: '**Resolving horizontal and vertical collision in the same step.** If you move diagonally into a corner and resolve both axes at once, the player teleports to the wrong side. Resolve X first, then Y (or vice versa). Two separate passes prevent corner-case tunneling.',
    ei: 'Separating collision resolution into X and Y passes is the standard approach in every 2D physics engine. Box2D resolves constraints iteratively per axis. Your split-axis resolution is the tile-based equivalent of the same principle.',
    st: 'The RPG resolves collision on a grid — movement is always axis-aligned, so the problem does not arise. The Shooter resolves overlap by pushing entities apart along the shortest axis. Split-axis resolution is a 2D platformer essential that other genres handle differently.' },
  { file: 'lesson-platformer-14-collectible-coins.ts',
    bt: '**Removing a coin from the tile grid by setting it to 0 and forgetting to increment the score.** Always pair state changes: remove the coin AND update the counter in the same function. Separating them creates bugs where one happens without the other.',
    ei: 'Super Mario Bros uses the same pattern: coin tile becomes empty tile, coin counter increments, and a particle spawns — all in one function call. Atomic state transitions (all-or-nothing) prevent desynchronized game state.',
    st: 'The RPG collects items by removing them from the entity array and adding to inventory — the same atomic removal + counter update. The Shooter deactivates bullet entities on hit and increments score. Collect-and-count is universal.' },
  { file: 'lesson-platformer-15-milestone-mini-level.ts',
    bt: '**Declaring the milestone complete without testing edge cases.** Walk into every wall corner, jump at every ledge edge, collect every coin. If even one collision fails or one coin is missed, the tile system has a bug.',
    ei: 'Nintendo playtests every Mario level by having testers try to break every surface. The QA phrase is "walk every wall." Your milestone requires the same discipline: systematic verification of every collidable tile.',
    st: 'RPG L15 and Shooter L15 hit the same data layout milestone. The foundation is identical: stable state, correct collision, functional pickups. Genre-specific features build on this shared architecture.' },
  { file: 'lesson-platformer-20-milestone-two-level-transition.ts',
    bt: '**Loading the next level without resetting transient state.** If enemy positions, particle effects, or physics state from level 1 bleed into level 2, the transition is broken. Reset all per-level state, preserve only persistent state (score, lives).',
    ei: 'Mega Man clears all enemy and projectile data on room transition, keeping only player HP and weapon energy. The clean-slate approach prevents ghost entities from previous rooms appearing in the new room.',
    st: 'The RPG transitions between rooms with a similar clean-slate approach. The Crawler transitions between dungeon floors. Every path faces the same challenge: cleanly separate per-level state from persistent state during transitions.' },
  { file: 'lesson-platformer-24-checkpoint-save-v0.ts',
    bt: '**Saving the entire game state instead of just the checkpoint data.** You do not need to save particle positions or animation frames. Identify the minimal set of data needed to resume: player position, collected coins, current level, score.',
    ei: 'Dark Souls saves a minimal state snapshot at bonfires: player position, stats, inventory, and world flags. Transient state (enemy positions, projectiles) regenerates on load. Minimal snapshots make save files small and load times fast.',
    st: 'The RPG saves player stats, inventory, and room ID — not enemy animation frames. The Shooter saves score, wave, and lives. Every path learns the same lesson: save the minimum state needed to reconstruct the game, not the entire memory image.' },
  { file: 'lesson-platformer-25-restart-resume.ts',
    bt: '**Testing restart but not resume.** A restart that works does not prove load works. Save, close, reload, and verify the state matches. The full round-trip test (save + load + verify) is the real proof of correctness.',
    ei: 'Professional QA teams run "save-quit-load" cycles hundreds of times with different game states. The round-trip test catches serialization bugs that manual restart testing misses — field order, type size, and endianness issues.',
    st: 'The RPG and Shooter test the same save-quit-load cycle. The Crawler tests permadeath save integrity. Round-trip verification is the universal test for any save system regardless of genre.' },
  { file: 'lesson-platformer-26-entity-pool-v0.ts',
    bt: '**Using a linked list for the free list.** A linked list of free slots requires pointer chasing, which defeats the cache benefits of a pool. Use an integer index stack: push freed indices, pop to allocate. Contiguous integers, zero pointers.',
    ei: 'Entity pools in professional engines (Unreal, Unity DOTS) use index-based free lists for cache efficiency. The pool is a contiguous array; the free list is a stack of integer indices. Your implementation follows the same zero-pointer pattern.',
    st: 'The Shooter uses entity pools for bullets, enemies, and powerups. The RPG pools dungeon entities. Pool-based allocation is the most universal optimization in the curriculum — every path implements it because heap allocation in the game loop is never acceptable.' },
  { file: 'lesson-platformer-27-particle-pool-v0.ts',
    bt: '**Allocating particles with new/malloc when the player collects a coin.** Coin collection can happen every frame in a dense level. If each collection spawns 10 particles with new, that is 10 heap allocations per frame. Use the pool — zero allocation, same visual result.',
    ei: 'Every particle system in professional engines uses pool allocation. Unity ParticleSystem pre-allocates its maximum capacity. Unreal Niagara uses pool-backed emitters. Pool-based particles maintain the heap-freeze guarantee under heavy visual effects.',
    st: 'The Shooter pools bullet particles and explosion effects. The RPG pools combat text popups. Particle pools are universal because particles are the highest-frequency spawn/despawn entities in any game.' },
  { file: 'lesson-platformer-28-allocation-counter-v0.ts',
    bt: '**Ignoring allocations that happen "only once per level load."** Even one allocation per level transition is a stall that causes a visible hitch. The goal is zero heap allocations during gameplay — no exceptions, no excuses.',
    ei: 'Carmack set the standard: zero heap allocations during gameplay in Doom and Quake. Every allocation is a potential stall, a potential fragmentation event, and a potential leak. Your counter makes this discipline measurable.',
    st: 'RPG L28 and Shooter L28 track the same metric. The Crawler counts allocations too. Allocation counting is the universal health check — every path must prove zero heap activity during the game loop.' },
  { file: 'lesson-platformer-29-leak-trap-demo.ts',
    bt: '**Fixing the intentional leak to make the counter stop.** The point of the demo is to show what happens when you use new without delete. Leave the leak active, watch the counter climb, then replace it with pool allocation and watch the counter stay at zero.',
    ei: 'Valgrind and AddressSanitizer detect leaks by tracking every allocation and matching it with a free. Your allocation counter is a manual version of the same technique — instrument the allocator to catch leaks in real time.',
    st: 'RPG L29 and Shooter L29 demonstrate the same leak trap. The lesson is universal: heap allocation in the game loop is a bug, and pools are the cure. Every path proves immunity by showing the allocation counter stays at zero.' },
  { file: 'lesson-platformer-30-gate-a-heap-freeze.ts',
    bt: '**Thinking "zero allocations" means "no dynamic behavior."** Pre-allocated pools give you all the dynamic behavior you need — spawn, despawn, recycle — without touching the heap. The constraint is on allocation, not on dynamism.',
    ei: 'Console games on PlayStation and Xbox must pass memory certification — no unbounded allocation growth during gameplay. The heap-freeze pattern you are implementing is how every shipped console game passes this requirement.',
    st: 'RPG L30, Shooter L30, and Crawler L30 all hit the same gate. Heap freeze is the most universal engineering gate in the curriculum — four paths, one standard: zero allocations in the game loop.' },
  { file: 'lesson-platformer-32-render-module-split.ts',
    bt: '**Calling DrawRectangle inside the physics update loop.** Rendering mixed with game logic means you cannot change draw order without changing update order. Separate update and render into distinct passes that run in sequence.',
    ei: 'Every game engine separates update from render. Unity runs FixedUpdate, Update, then LateUpdate (render). The separation enables fixed timestep, headless testing, and double-buffering — none of which work if update and render are interleaved.',
    st: 'RPG L32 and Shooter L32 split render the same way. The Crawler renders in a separate BeginMode3D block. Update-then-render is the universal game loop pattern, discovered independently by every engine developer.' },
  { file: 'lesson-platformer-33-physics-module-split.ts',
    bt: '**Scattering velocity and position updates across multiple functions.** If gravity is applied in one function and horizontal movement in another with rendering between them, the physics state is inconsistent during the render pass. Consolidate all physics into one system.',
    ei: 'Separating physics into its own system enables headless simulation — you can run physicsSystem() without rendering to test collision, replay input, or fast-forward time. Celeste uses a similar isolated physics pass for its TAS (tool-assisted speedrun) mode.',
    st: 'RPG L17 isolates its resolve pass. Shooter L33 isolates movement. Each path extracts physics/movement into a standalone system — the name differs (resolve, physics, movement) but the isolation principle is identical.' },
  { file: 'lesson-platformer-34-collision-module-split.ts',
    bt: '**Applying collision responses (push out of wall, kill enemy) inside the detection loop.** Detect all collisions first into a result list, then apply responses in a separate pass. Mixing detection with response creates order-dependent bugs when multiple collisions occur in one frame.',
    ei: 'Professional physics engines split collision into broadphase (find candidate pairs), narrowphase (exact test), and resolution (apply response). Your split follows the same pipeline: detect first, respond second. This separation makes debugging trivial — you can log all detections before any state changes.',
    st: 'RPG L18 isolates combat resolution. Shooter L34 isolates collision response. The Crawler separates hit detection from damage. Detection-then-resolution prevents order-dependent bugs in every game genre.' },
  { file: 'lesson-platformer-35-system-pipeline-gate.ts',
    bt: '**Running systems in arbitrary order.** If collision runs before physics, you detect collisions with stale positions from last frame. Define and enforce the pipeline order: Input > Physics > Collision > Cleanup > Render.',
    ei: 'Unity defines execution order numerically. Unreal uses tick groups. ECS frameworks use explicit system scheduling. Your gameFrame() function is the manual equivalent — a fixed pipeline that guarantees systems run in the correct sequence.',
    st: 'RPG L15 and Shooter L35 enforce the same system pipeline. The Crawler runs 3D systems in a fixed order. Pipeline ordering is a universal architecture constraint — every path must guarantee systems run in the correct sequence.' },
  { file: 'lesson-platformer-37-one-way-platforms.ts',
    bt: '**Blocking the player from passing through a one-way platform from below.** The whole point is that the player can jump up through it and land on top. Only resolve collision when the player is moving downward and their feet are above the platform top edge.',
    ei: 'Super Mario Bros, Donkey Kong Country, and Celeste all implement one-way platforms with the same rule: collide only when velocity.y > 0 and player.bottom <= platform.top + epsilon. The directional check is always velocity-based, never position-based.',
    st: 'The RPG has no vertical movement — all collision is grid-based. The Shooter has no platforms. One-way platforms are a platformer-specific mechanic, but the concept of directional collision filtering applies to any game with selective collision rules.' },
  { file: 'lesson-platformer-42-wall-slide.ts',
    bt: '**Applying wall slide friction without checking if the player is actually pressing toward the wall.** If the player jumps near a wall without pressing into it, they should not stick. Only activate wall slide when the player holds the direction key toward the wall AND is airborne AND falling.',
    ei: 'Mega Man X introduced wall sliding as a core mechanic. Celeste refined it with variable slide speed based on how long you hold the direction. Hollow Knight uses wall cling with a stamina timer. The mechanic always requires intentional directional input.',
    st: 'The RPG and Shooter have no wall interaction. The Crawler uses wall collision for 3D navigation. Wall sliding is uniquely platformer, but the pattern of combining multiple conditions (airborne + falling + input direction) into a movement state is universal game logic.' },
  { file: 'lesson-platformer-46-hazard-tiles.ts',
    bt: '**Killing the player instantly on hazard contact without any feedback.** The player needs to understand what killed them. Flash the screen, play a sound cue, and show where the hazard is. Instant death without visual feedback feels unfair and teaches nothing.',
    ei: 'Super Meat Boy uses instant-death hazards but provides immediate respawn and a death replay. Celeste shows a death particle burst at the exact contact point. Visual feedback on death is what separates "hard but fair" from "frustrating."',
    st: 'The RPG uses damage numbers to communicate HP loss. The Shooter flashes the player ship on hit. Every path needs clear damage feedback — the implementation differs (tile flash, particle burst, screen shake) but the UX principle is universal: show the player what happened.' },
  { file: 'lesson-platformer-47-enemy-patrol.ts',
    bt: '**Making enemies reverse direction by checking pixel position exactly.** Floating-point positions rarely hit exact values. Check if the enemy has passed the waypoint (position >= target) rather than checking for equality (position == target). Threshold checks are reliable; exact checks are not.',
    ei: 'Castlevania and Mega Man enemies use simple left-right patrol between two fixed points. The patrol is defined as data (start_x, end_x, speed) not as code. Your waypoint-based patrol follows the same data-driven pattern used since the NES era.',
    st: 'The RPG patrols enemies between grid waypoints. The Shooter uses sine-wave movement patterns. The Crawler patrols enemies in 3D corridors. Patrol behavior is universal — the coordinate system changes, but "move between two points and reverse" is the same algorithm everywhere.' },
  { file: 'lesson-platformer-51-enemy-types-data-driven.ts',
    bt: '**Creating a new class for each enemy type.** Classes with virtual methods add indirection and break SoA layout. Use an enum type field and a stat table: each enemy type is a row of numbers (HP, speed, damage, score), not a class hierarchy.',
    ei: 'Unity abandoned MonoBehaviour inheritance for DOTS components. Hollow Knight defines enemy types as data tables — each enemy ID maps to stats, sprites, and behavior IDs. Your enum + table approach achieves the same result: new enemy types are data, not code.',
    st: 'The RPG uses strategy tables for enemy behavior. The Shooter uses data-driven enemy types (L42). The Crawler uses spawn budgets with type IDs. Data-driven entity types scale to any number of types without code changes — the standard across all paths.' },
  { file: 'lesson-platformer-52-projectile-enemies.ts',
    bt: '**Spawning projectiles at the enemy center instead of at a muzzle offset.** Bullets that appear from the middle of an enemy look wrong. Define a muzzle offset relative to the enemy facing direction so projectiles spawn from a visually correct position.',
    ei: 'Mega Man enemies fire projectiles from defined muzzle points — each enemy sprite has a specific launch position. Contra enemies use directional firing with aim-at-player logic. Projectile spawn points are visual data, not hardcoded offsets.',
    st: 'The Shooter fires bullets from the ship nose. The Crawler fires projectiles from 3D enemy positions. Projectile origin offsets are universal — every path that fires projectiles needs a muzzle position defined per entity type.' },
  { file: 'lesson-platformer-53-hitbox-hurtbox-split.ts',
    bt: '**Using one bounding box for both dealing and receiving damage.** If the player sword hitbox is the same as the player hurtbox, the player takes damage from their own attack area. Separate hitboxes (deal damage) from hurtboxes (receive damage) as distinct collision layers.',
    ei: 'Fighting games pioneered the hitbox/hurtbox split — Street Fighter uses green (hurtbox), red (hitbox), and blue (throwbox) overlays for frame data analysis. Hollow Knight uses the same split: the nail swing hitbox is separate from the knight hurtbox.',
    st: 'The RPG uses turn-based targeting — no real-time hitboxes needed. The Shooter uses single bounding boxes for simple AABB collision. Your hitbox/hurtbox split is the most granular collision system across all paths, essential for melee combat fairness.' },
  { file: 'lesson-platformer-54-invulnerability-frames.ts',
    bt: '**Making the player invisible during i-frames.** Invisible players cannot see where they are. Flash the sprite (toggle visibility every 4 frames) so the player knows they are invulnerable and can still track their position.',
    ei: 'Castlevania and Mega Man both use sprite flashing during i-frames. Celeste uses a color tint shift. Hollow Knight uses a brief white flash on hit followed by reduced opacity. The visual cue communicates "you are safe" without hiding the character.',
    st: 'The Shooter uses shield timers for temporary immunity. The RPG does not have real-time i-frames (turn-based). Timer-based temporary immunity is a universal pattern — the visual feedback differs, but the countdown-to-vulnerable logic is identical.' },
  { file: 'lesson-platformer-55-milestone-combat-system.ts',
    bt: '**Declaring combat complete without testing enemy-player and player-enemy interactions together.** Stomp an enemy, take a hit, verify i-frames activate, collect a pickup, verify score updates. All combat systems must work simultaneously, not just individually.',
    ei: 'Hollow Knight combat integrates nail strikes, spell damage, enemy contact damage, i-frames, and soul collection into one seamless system. The milestone tests the same integration: every combat interaction must coexist without breaking another.',
    st: 'The RPG validates combat resolution at L40. The Shooter validates bullet-enemy-powerup interactions. Every path has a combat milestone that proves all damage-dealing and damage-receiving systems integrate correctly.' },
  { file: 'lesson-platformer-56-boss-entity-v0.ts',
    bt: '**Giving the boss the same collision box as regular enemies.** Bosses are larger entities with multiple hit zones. A boss-sized bounding box may need sub-hitboxes for weak points, or at minimum a larger collision rect than standard enemies.',
    ei: 'Mega Man bosses have multiple phases with distinct attack patterns and vulnerable windows. Hollow Knight bosses use state machines with idle, attack, stagger, and transition states. Your boss entity is the most complex single entity in the game.',
    st: 'The Shooter implements boss entities with multi-phase attacks (L56). The RPG has no real-time bosses. Boss entities test whether your entity system can handle entities with significantly more state and behavior than normal enemies.' },
  { file: 'lesson-platformer-57-boss-attack-patterns.ts',
    bt: '**Hardcoding boss attacks in a chain of if/else statements.** Each new attack pattern means more branches and more bugs. Store patterns as data: { type: CHARGE, speed: 5.0, duration: 60, cooldown: 90 }. The boss system reads data, not code.',
    ei: 'Cuphead defines every boss attack as data entries: timing, projectile count, angle spread, and phase trigger. Designers iterate on boss difficulty by changing data values, not by editing code. Your data-driven patterns follow the same production workflow.',
    st: 'The Shooter defines attack patterns as data tables (L57). The RPG defines combat abilities in lookup tables. Data-driven attack definitions are universal: designers create content by editing data, not by writing and debugging new code.' },
  { file: 'lesson-platformer-58-pickup-items.ts',
    bt: '**Applying pickup effects immediately without visual feedback.** If the player collects a health pickup, show the HP increase with a floating number or flash the health bar. Silent stat changes feel broken — the player wonders "did that do anything?"',
    ei: 'Metroid uses a distinct jingle and flash for every item pickup. Hollow Knight shows a soul particle stream when collecting soul. The feedback loop (collect, sound, visual, stat change) makes every pickup feel rewarding.',
    st: 'The RPG shows damage numbers and item notifications. The Shooter shows score popups on kills. Every path needs item feedback — the visual differs (floating text, particle burst, HUD flash) but the principle is universal: acknowledge every player interaction.' },
  { file: 'lesson-platformer-59-score-timer-hud.ts',
    bt: '**Drawing HUD text at world coordinates instead of screen coordinates.** The HUD should not scroll with the camera. Draw score and timer at fixed screen positions (top-left, top-right) after the camera transform, not inside it.',
    ei: 'Every game engine draws the HUD as a separate pass after world rendering. The HUD reads observable state (score, time, HP) and draws at screen-anchored positions. Your HUD follows the same decoupled architecture used in Unity Canvas and Unreal UMG.',
    st: 'The RPG and Shooter implement HUD systems the same way — screen-anchored text drawn after world rendering. The Crawler overlays 3D HUD elements. HUD rendering is always the last draw pass, reading game state without modifying it.' },
  { file: 'lesson-platformer-60-milestone-complete-combat.ts',
    bt: '**Skipping boss testing because "regular enemies work."** The boss is the most complex entity in the game. If boss phases, attack patterns, and death sequences work correctly, everything simpler definitely works. Test the boss thoroughly.',
    ei: 'Nintendo tests boss fights with a dedicated QA team that plays each phase hundreds of times. Every attack window, every vulnerable period, every transition must feel fair and function correctly. Your milestone requires the same thorough boss verification.',
    st: 'The Shooter validates its complete combat system at L60. The RPG validates at L40. Every path reaches a "combat is done" milestone where all offensive and defensive systems must integrate seamlessly.' },
  { file: 'lesson-platformer-61-save-v1-versioned.ts',
    bt: '**Storing the version number at the end of the save file.** If you read the version first, you can choose the correct deserialization path before reading any data. Version at the end means you have already read everything blindly.',
    ei: 'PNG, ZIP, and SQLite all store a magic number and version in the first bytes. Game save formats follow the same convention: identification first, data second. Your versioned save header follows the industry-standard file format pattern.',
    st: 'RPG L24 and Shooter L61 implement versioned saves the same way. Every path stores version first, then data. The serialization pattern is universal because the problem (forward compatibility) is universal.' },
  { file: 'lesson-platformer-62-save-checksum.ts',
    bt: '**Computing the checksum over the entire file including the checksum field itself.** The checksum must cover only the data portion. On load, recompute the hash over the data and compare it to the stored checksum. Including the checksum in its own hash guarantees a mismatch.',
    ei: 'CRC32, used in ZIP files and Ethernet frames, detects accidental corruption with 99.998% reliability. Your save checksum follows the same pattern: hash the data, store the hash, verify on load.',
    st: 'RPG and Shooter implement save checksums the same way. The Crawler stores checkpoint integrity hashes. Data integrity verification is a universal requirement for any system that persists state to disk.' },
  { file: 'lesson-platformer-63-load-migration.ts',
    bt: '**Failing to load old save files after a format change.** Players lose progress when you update the save format. Migration means: read old format, convert to new format, save in new format. Each version bump needs a migration function.',
    ei: 'Database migrations (Rails, Django, Flyway) apply sequential transforms to upgrade schema versions. Game save migration is the same problem: each version change needs a transform function that upgrades old data to the new format.',
    st: 'RPG L24 and Shooter L63 handle save migration. Every path faces the same challenge: game updates must not break existing save files. Version-checked deserialization with migration functions is the standard solution across all genres.' },
  { file: 'lesson-platformer-64-input-log-v0.ts',
    bt: '**Recording processed actions ("jumped at frame 50") instead of raw key states ("SPACE down at frame 50").** If you change jump logic later, action-based logs break. Raw input logs stay valid even when gameplay code changes.',
    ei: 'Doom recorded raw input as "tics" — one complete input snapshot per game frame. This made .lmp demo files tiny and perfectly reproducible across different builds. Your per-frame input log follows the same design from 1993.',
    st: 'RPG, Shooter, and Crawler all record raw input per frame. The input types differ (arrow keys, mouse, WASD+mouse) but the principle is identical: capture raw input, not derived actions. Raw logs survive code changes.' },
  { file: 'lesson-platformer-65-milestone-replay-a-run.ts',
    bt: '**Testing replay for only 10 frames.** Determinism bugs often surface hundreds of frames in, when floating-point drift accumulates. Record a full 60-second gameplay session, replay it, and verify the state signature matches at every frame.',
    ei: 'Speedrun communities rely on replay files to verify world records. A replay that diverges from the recording is evidence of a bug or cheat. Your replay milestone tests the same guarantee: identical input produces identical output.',
    st: 'RPG, Shooter, and Crawler all hit the same replay milestone. The test is identical: play, record, replay, verify. Determinism is a cross-path requirement because replay and save/load both depend on it.' },
  { file: 'lesson-platformer-66-replay-playback.ts',
    bt: '**Mixing live input with replay input during playback.** If the player presses a key during replay, it should be ignored. Swap the input source: live mode reads keyboard, replay mode reads the log. The rest of the game must not know the difference.',
    ei: 'The "input source abstraction" pattern lets the same game loop accept live, recorded, or network input. Professional engines use this for replays, tutorials, and AI bots. Super Meat Boy uses it to show death replays of all previous attempts simultaneously.',
    st: 'RPG, Shooter, and Crawler implement the same input source swap. The abstraction is identical: the game loop reads from an InputSnapshot, and the source (live keyboard, replay log, network) is swapped externally.' },
  { file: 'lesson-platformer-67-determinism-pitfalls.ts',
    bt: '**Using std::sort without a stable tiebreaker.** std::sort is not guaranteed to be stable — equal elements can swap order between runs, producing different entity processing order. Use std::stable_sort or add entity ID as a tiebreaker in the comparator.',
    ei: 'Floating-point determinism is the number one cause of desync in networked games. Different compilers optimize x87 vs SSE differently. RTS games like Age of Empires use fixed-point math to avoid this entirely. Your pitfall catalog documents the traps.',
    st: 'RPG, Shooter, and Crawler face the same pitfalls. Iteration order, unstable sort, and floating-point precision affect every path equally. The determinism discipline is shared across all game genres.' },
  { file: 'lesson-platformer-68-state-signature-verify.ts',
    bt: '**Only hashing player position and forgetting score, coins collected, and enemy states.** Every gameplay-relevant value must be in the signature. If the score diverges but the hash does not catch it, your signature is incomplete.',
    ei: 'Age of Empires computes a per-frame hash of all game state for multiplayer sync checking. Any divergence triggers a desync warning. Your state signature serves the same purpose for single-player replay verification.',
    st: 'RPG L23 and Shooter L68 compute state signatures. The Crawler computes floor state hashes. The hash function and included fields differ, but the purpose is identical: detect state divergence between recording and playback.' },
  { file: 'lesson-platformer-69-replay-verification-test.ts',
    bt: '**Running the verification only once with one seed.** A test that passes with seed 42 may fail with seed 7. Run verification with at least 5 different seeds and gameplay patterns to catch determinism bugs that depend on specific input sequences.',
    ei: 'Professional QA runs hundreds of automated replay tests nightly — each with different seeds, durations, and player behaviors. One passing test proves nothing. Confidence comes from volume and variety.',
    st: 'RPG, Shooter, and Crawler run the same replay verification tests. The testing pattern is path-universal: record diverse sessions, replay them all, assert zero signature mismatches.' },
  { file: 'lesson-platformer-70-gate-b-replay-determinism.ts',
    bt: '**Passing the gate with a 10-second replay.** Short replays might pass when long replays fail because floating-point drift accumulates over time. Test with extended gameplay sessions to expose subtle determinism bugs.',
    ei: 'Lockstep determinism is proven by extended testing under varied conditions. Professional studios run overnight replay suites to build confidence. StarCraft 2 runs thousands of replay verification tests before each patch ships.',
    st: 'RPG L70, Shooter L70, and Crawler L70 all hit the same gate. Replay determinism is the most engineering-intensive gate in the curriculum — all four paths must prove bit-perfect reproducibility.' },
  { file: 'lesson-platformer-71-profiling-timers.ts',
    bt: '**Profiling in debug mode.** Debug builds add bounds checking, assertion evaluation, and disable optimizations. Always profile with -O1 or higher. The hot path in debug may not be the hot path in release.',
    ei: 'The Cherno demonstrates profiling with scoped timers that measure each system independently. Chrome Tracing format exports let you visualize frame breakdowns. Your per-system timer follows the same instrumentation pattern.',
    st: 'RPG L71, Shooter L71, and Crawler L51 all add profiling timers. Measurement is the first step of optimization in every path — you cannot improve what you have not measured.' },
  { file: 'lesson-platformer-72-hot-path-audit.ts',
    bt: '**Optimizing a function that takes 0.1ms when collision takes 4ms.** The hot path is the code that consumes the most frame time. Always optimize the biggest bottleneck first. Profiling data tells you what to fix — intuition does not.',
    ei: 'The Pareto principle applies to optimization: 20% of the code consumes 80% of the frame time. In platformers, tile collision checks and entity iteration are almost always the hot path. Audit those first, leave cold code alone.',
    st: 'RPG L72 and Shooter L72 audit their hot paths too. Every path converges on the same optimization discipline: profile, identify the bottleneck, optimize it, re-profile to verify the improvement.' },
  { file: 'lesson-platformer-73-spatial-grid-entities.ts',
    bt: '**Using a grid cell size smaller than the largest entity.** If an entity spans multiple cells, you must check all neighboring cells for every query. Size the grid so the most common entity fits in one cell. Profile different cell sizes to find the optimum.',
    ei: 'The spatial grid (uniform grid acceleration structure) trades memory for speed: O(1) cell lookup instead of O(n) linear scan. Every 2D physics engine uses spatial acceleration — grids for uniform entity sizes, quadtrees for mixed sizes.',
    st: 'The RPG uses direct grid lookup (grid[y][x]). The Shooter uses a spatial grid for bullet-enemy queries (L36). The Crawler uses spatial hashing. Same goal (fast neighbor queries), different data structures tuned to different entity distributions.' },
  { file: 'lesson-platformer-74-pool-stats.ts',
    bt: '**Setting pool capacity based on average usage instead of peak usage.** Pools must handle the worst case, not the average case. Track peak_used across the entire session and size the pool to peak + a 20% margin.',
    ei: 'Unity Profiler shows pool utilization graphs with peak markers. Unreal tracks peak object counts per pool. Your pool stats dashboard is the manual equivalent — peak tracking guides correct pool sizing.',
    st: 'RPG L74 and Shooter L74 audit pool utilization. The Crawler audits pool stats too. Pool sizing is a universal optimization task — too small causes overflow, too large wastes memory. Peak tracking guides the right size.' },
  { file: 'lesson-platformer-75-milestone-stress-test.ts',
    bt: '**Stress testing with the same entity count as normal gameplay.** The point is to find the breaking point. Spawn 100+ enemies, 200+ coins, and 50+ particles simultaneously. If frame rate stays above 60fps, the architecture scales.',
    ei: 'Professional studios run "soak tests" — leaving the game running under maximum load for hours. Memory leaks, frame drops, and crashes that hide during normal play surface under sustained stress. Your test follows the same principle.',
    st: 'Shooter L75 stress tests with 200+ bullets and 50+ enemies. RPG L75 tests with 50 entities. Every path proves performance at scale — the entity count differs, but the principle is identical: verify the architecture handles peak load.' },
  { file: 'lesson-platformer-76-slope-collision-v0.ts',
    bt: '**Treating slopes as regular solid tiles.** A slope is not a binary solid/empty tile — it has a height gradient across its width. Sample the slope height at the player X position within the tile: height = slope_start + (player_x_in_tile / tile_width) * (slope_end - slope_start).',
    ei: 'Sonic the Hedgehog uses height maps per tile — each 16px tile stores a column of heights that define the surface. This approach handles arbitrary slopes, curves, and loops. Your slope collision is the simplified version of the same technique.',
    st: 'The RPG has flat grid collision — no slopes. The Shooter has no terrain. The Crawler uses 3D floor planes. Slope collision is uniquely platformer, but the concept of sampling terrain height at a point applies to any game with non-flat ground.' },
  { file: 'lesson-platformer-77-camera-deadzone.ts',
    bt: '**Making the camera follow the player with zero deadzone.** A camera that tracks every pixel of movement creates a nauseating jitter effect. The deadzone is the area where the player can move freely without the camera following. Start with a 64x64 pixel deadzone and tune from there.',
    ei: 'Celeste uses a complex camera system with horizontal and vertical deadzones, look-ahead, and vertical bias for falls. Hollow Knight uses room-locked cameras with smooth transitions. Your deadzone camera is the foundation that all advanced camera systems build upon.',
    st: 'The RPG camera is room-locked (no smooth follow needed). The Shooter camera is fixed. The Crawler uses first-person camera. Camera deadzones are a platformer and side-scroller essential — the technique is specific to 2D scrolling games.' },
  { file: 'lesson-platformer-78-parallax-background.ts',
    bt: '**Moving all parallax layers at the same speed.** If every layer scrolls identically, there is no depth illusion. Layers further from the camera scroll slower: far background at 0.2x, mid background at 0.5x, near foreground at 0.8x camera speed.',
    ei: 'Parallax scrolling dates back to Moon Patrol (1982) and became standard in every 2D game from Sonic to Ori. The illusion of depth is achieved purely by scroll-speed ratios — no 3D math required, just multiplication.',
    st: 'The Shooter uses vertical parallax for scrolling star fields (L48). The RPG has no parallax (top-down grid). The Crawler uses actual 3D perspective. Parallax is the 2D solution to the depth problem that 3D games solve with perspective projection.' },
  { file: 'lesson-platformer-79-config-file.ts',
    bt: '**Storing config values in the same file as game logic.** When a designer wants to change jump height, they should not need to search through physics code. A dedicated config struct or file separates tuning from implementation.',
    ei: 'Professional studios externalize all balance data — movement speed, jump height, gravity, enemy HP — into data files or config structs. Designers iterate on feel by changing data, not recompiling code. Your config struct is the first step.',
    st: 'RPG L87 and Shooter L86 externalize difficulty config. Every path separates tuning from logic. The config format varies (struct, table, file) but the principle is identical: designers change data, programmers change code.' },
  { file: 'lesson-platformer-80-milestone-performance-report.ts',
    bt: '**Writing "performance feels good" without numbers.** A performance report needs data: frame time (ms), entity count, collision checks, pool utilization, memory usage. Subjective "feels smooth" is not a metric.',
    ei: 'Professional game studios produce performance reports with every milestone build. The report includes frame budget breakdown, regression comparisons, and target hardware benchmarks. Your report follows the same standard.',
    st: 'RPG L75, Shooter L80, and Crawler L55 produce similar reports. The metrics differ by genre, but every path must quantify performance with real numbers, not subjective impressions.' },
  { file: 'lesson-platformer-81-hud-v2-layout.ts',
    bt: '**Using absolute pixel positions for HUD elements.** If the window resizes or the aspect ratio changes, all positions break. Use anchor-relative positions: "10px from top-left corner" adapts to any resolution. Anchor + offset is the professional UI layout pattern.',
    ei: 'Every professional game engine uses anchor-based UI layout. Unity Canvas, Unreal UMG, and Godot Control nodes all position elements relative to screen edges or parent containers, never absolute pixel coordinates.',
    st: 'RPG L81 and Shooter L81 implement the same anchor-based HUD. The Crawler overlays 3D HUD elements. HUD architecture is identical across all paths — only the displayed information differs by genre.' },
  { file: 'lesson-platformer-82-screen-shake.ts',
    bt: '**Applying screen shake by moving entity positions instead of offsetting the camera.** Moving entities permanently displaces them. Shake should be a temporary render-time offset applied to the camera, never to the game state. When the shake ends, everything is exactly where it was.',
    ei: 'Vlambeer (Nuclear Throne, Ridiculous Fishing) popularized screen shake as a "game feel" essential. A 3-frame, 4-pixel shake on enemy stomp makes the impact feel powerful. The effect is pure presentation — zero game state modification.',
    st: 'RPG L82 adds combat feedback shake. Shooter L82 adds explosion shake. The Crawler could add 3D camera shake. Screen shake is the simplest high-impact juice effect — render-only, zero gameplay side effects, universal across all genres.' },
  { file: 'lesson-platformer-83-particle-effects.ts',
    bt: '**Allocating particles with new when the player lands or stomps.** Landing particles spawn every time the player touches ground — potentially every frame. Use the particle pool. Zero allocation, maximum visual impact.',
    ei: 'Celeste uses particles for everything: dust on landing, crystals on dash, feathers on death. Each effect is a burst of pool-allocated particles with unique colors and velocities. Your particle effects follow the same pool-based design.',
    st: 'The Shooter uses pool particles for explosions (L83). The RPG uses particles for combat feedback. Every path uses pool-based particles because particles are the highest-frequency spawn/despawn entities in any game.' },
  { file: 'lesson-platformer-84-sprite-animation-v0.ts',
    bt: '**Advancing animation frames using a frame counter instead of delta time.** On a 120fps monitor, animations play twice as fast as on 60fps. Use a time accumulator: add dt each frame, advance the animation frame when the accumulator exceeds frame_duration.',
    ei: 'Sprite animation with time accumulators is the industry standard. Celeste runs animations at fixed durations regardless of frame rate. Hollow Knight uses the same delta-time approach for all character and enemy animations.',
    st: 'RPG L83 and Shooter L84 implement the same delta-time animation. The Crawler uses 3D model animation. Frame-rate-independent animation is mandatory across all paths — the technique is universal.' },
  { file: 'lesson-platformer-85-milestone-juiced-platformer.ts',
    bt: '**Adding juice without measuring frame impact.** Screen shake, particles, and animations all cost CPU time. Profile the render pass before and after adding juice effects. If effects drop the frame rate, reduce particle counts or simplify animations.',
    ei: 'Jan Willem Nijman (Vlambeer) lists screen shake, hit pause, particles, and sound as the minimum juice checklist. Celeste layers dust particles, squash-and-stretch, hair animation, and camera effects. Your milestone tests the same integration.',
    st: 'RPG L85, Shooter L85, and Crawler L60 all hit juice milestones. The effects differ by genre (2D particles vs 3D particles vs sprite animations) but the principle is universal: feedback and polish make games feel alive.' },
  { file: 'lesson-platformer-86-difficulty-config.ts',
    bt: '**Storing difficulty multipliers in scattered constants.** If gravity is in physics.cpp, enemy speed is in enemy.cpp, and jump height is in player.cpp, tuning difficulty requires editing three files. A single DifficultyConfig struct centralizes all balance values.',
    ei: 'Celeste externalizes all difficulty-related values: dash count, stamina, game speed, and invulnerability. Designers iterate on accessibility by changing config values, not game logic. Your config struct enables the same rapid iteration.',
    st: 'RPG L87 and Shooter L86 implement data-driven difficulty. Every path externalizes balance into data. The config format varies but the principle is identical: separate tuning from logic so designers can iterate without recompiling.' },
  { file: 'lesson-platformer-87-assist-mode.ts',
    bt: '**Making assist mode a single "easy" toggle.** Players need granular control: slower game speed, more coyote time, infinite dashes, invulnerability. Independent toggles respect player agency more than a binary easy/hard selection.',
    ei: 'Celeste pioneered granular assist mode: game speed slider, infinite stamina, infinite dashes, and invulnerability as independent toggles. The key insight: accessibility is not one setting but a set of dials players combine to match their abilities.',
    st: 'RPG L86 and Shooter L87 implement the same granular assist concept. Accessibility as a first-class feature — not a difficulty afterthought — is a universal game design principle across all paths.' },
  { file: 'lesson-platformer-88-crash-proofing.ts',
    bt: '**Only handling errors in the happy path.** Edge cases crash silently: invalid tile index, empty pool on spawn, out-of-bounds level data. Validate at every system boundary — function entry, file load, pool access, array index.',
    ei: 'Defensive programming in production games means: never crash, always degrade gracefully. If the tile index is out of bounds, return empty. If the pool is full, skip the spawn. The game continues, and the developer sees the warning.',
    st: 'RPG L88 and Shooter L88 crash-proof the same boundaries. The Crawler validates 3D coordinate ranges. Every path validates the same entry points: file I/O, user input, pool access, array bounds. The crash-proofing checklist is path-universal.' },
  { file: 'lesson-platformer-89-dead-code-cleanup.ts',
    bt: '**Commenting out dead code instead of deleting it.** Version control (git) preserves history. Commented-out code confuses future readers who wonder if it should be uncommented. Delete it — git log has the history if you ever need it back.',
    ei: 'Martin Fowler: "Dead code is a liability, not an asset." Every line of commented-out code is a line a future developer must read, understand, and decide to keep or delete. Remove the cognitive burden by removing the code.',
    st: 'RPG L89 and Shooter L89 perform the same cleanup. Code hygiene is universal: dead code, inconsistent naming, and copy-pasted logic are problems in every codebase regardless of game genre.' },
  { file: 'lesson-platformer-90-milestone-public-beta.ts',
    bt: '**Releasing a beta without automated tests.** Manual testing cannot catch regressions across 90 lessons of accumulated code. Collision tests, save/load round-trips, replay verification, and pool lifecycle tests catch what humans miss.',
    ei: 'Steam Early Access games ship with CI/CD pipelines that run automated test suites before each build reaches players. Your public beta milestone requires the same quality gate: tests pass, game does not crash, all systems functional.',
    st: 'RPG L90, Shooter L90, and Crawler all hit the same beta milestone. The criteria are identical: automated tests pass, no crashes in a 10-minute session, all systems functional. Genre is irrelevant to shipping quality.' },
  { file: 'lesson-platformer-91-build-id-version.ts',
    bt: '**Not including the build ID in crash reports or the window title.** When a tester reports a bug, you need to know which exact build they are running. Embed the build ID in the window title and any diagnostic output.',
    ei: 'Every shipped game includes build metadata: version number, commit hash, build date. Steam, PlayStation, and Xbox all require version identification for certification. Your build ID meets this universal requirement.',
    st: 'RPG L91 and Shooter L91 embed the same build ID. Version tracking is a shipping requirement across all paths — the format is identical because the need is identical.' },
  { file: 'lesson-platformer-92-unit-tests-physics.ts',
    bt: '**Testing physics with only one scenario.** Gravity, jump, air control, and ground friction each need multiple test cases: normal case, edge case (zero velocity), and boundary case (exactly on ground). Four scenarios per mechanic is the minimum.',
    ei: 'Box2D and Bullet Physics have extensive unit test suites that verify gravity, collision response, and constraint solving with known inputs and expected outputs. Your physics tests follow the same methodology: deterministic input, expected output, assert equality.',
    st: 'The Shooter tests pool and collision systems. The RPG tests combat formulas. Every path tests its core simulation with deterministic inputs and expected outputs. Physics verification is the platformer-specific version of the same testing discipline.' },
  { file: 'lesson-platformer-93-unit-tests-collision.ts',
    bt: '**Testing collision with overlapping rectangles only.** You need to test: overlapping (true), separated (false), touching edges (boundary case), one-way platform from above (true), one-way from below (false), and slope contact. Six categories cover the behavior space.',
    ei: 'Professional physics engines like Box2D test AABB overlap, edge cases (zero-size boxes), and degenerate inputs (NaN positions). Your collision test suite should cover the same breadth — normal, edge, and degenerate cases.',
    st: 'The RPG tests grid collision. The Shooter tests AABB overlap. Every path tests its core collision system with known inputs and expected outputs — the geometry differs but the testing methodology is identical.' },
  { file: 'lesson-platformer-94-unit-tests-level-parse.ts',
    bt: '**Testing level parsing with only valid level data.** What happens when a tile ID is out of range? When the grid has zero rows? When a row has fewer columns than expected? Test invalid inputs to verify graceful error handling.',
    ei: 'Fuzzing — feeding random and malformed data to parsers — is standard security practice. Your level parser tests follow the same principle: verify that malformed level data produces an error message, not a crash.',
    st: 'The RPG tests room data parsing. The Shooter tests wave table parsing. Every path that loads data from arrays or files must verify that malformed input does not crash the game. Parser robustness testing is universal.' },
  { file: 'lesson-platformer-95-gate-c-zero-warnings.ts',
    bt: '**Suppressing warnings with casts instead of fixing the underlying issue.** A (int) cast on a size_t silences the warning but the truncation bug remains. Fix the type mismatch at the source, not at the symptom.',
    ei: 'Google, Mozilla, and major game studios compile with -Wall -Werror. Warnings are treated as errors because they frequently indicate real bugs: unused variables, sign conversion, implicit narrowing, missing return statements.',
    st: 'RPG L95, Shooter L95, and Crawler all hit the same zero-warnings gate. Clean compilation is the universal quality bar — every path must pass before shipping.' },
  { file: 'lesson-platformer-96-readme-quickstart.ts',
    bt: '**Writing build instructions that only work on your machine.** Test the README on a clean environment or have someone else follow the steps. If step 3 fails because of an unmentioned dependency, the README is incomplete.',
    ei: 'Open-source projects succeed or fail based on README quality. A "clone, build, run" sequence that works on the first try drives adoption. Your quickstart should get a new developer from zero to a running platformer in under 5 minutes.',
    st: 'RPG L96, Shooter L96, and Crawler create READMEs. The structure is identical: project description, build instructions, controls, architecture overview. Documentation is a universal shipping requirement across all paths.' },
  { file: 'lesson-platformer-97-screenshot-capture.ts',
    bt: '**Capturing screenshots with debug overlays visible.** Collision boxes, profiling timers, and pool stats are developer tools. Portfolio screenshots should show clean gameplay. Disable all debug rendering before capturing.',
    ei: 'Steam store pages require specific screenshot formats and content quality. Screenshots are marketing assets — they represent the game to potential players. Clean, well-composed screenshots with good framing are a shipping requirement.',
    st: 'RPG L97, Shooter L97, and Crawler produce clean gameplay screenshots. Portfolio-quality screenshots are a universal deliverable — the game and the screenshots ship together.' },
  { file: 'lesson-platformer-98-final-content-pass.ts',
    bt: '**Polishing mechanics while leaving placeholder text.** "Enemy 1," "Level N," and "Score: %d" are not player-facing strings. Review every DrawText call and replace debug formatting with polished, readable presentation.',
    ei: 'QA teams flag placeholder text as a shipping blocker. Nintendo Treehouse reviews every player-facing string for clarity, consistency, and localization readiness. Your content pass follows the same standard.',
    st: 'RPG L98, Shooter L98, and Crawler perform the same content pass. Consistent naming, clear messaging, no placeholder text — the checklist is identical across all paths.' },
  { file: 'lesson-platformer-99-release-checklist.ts',
    bt: '**Skipping checklist items because they seem minor.** The one you skip is the one that causes a day-one bug. Checklists exist because complex systems have too many items for memory alone. Follow every item.',
    ei: 'NASA uses pre-launch checklists. Surgeons use pre-operation checklists. Game studios use release checklists. The pattern is universal: complex systems require systematic verification because humans forget under pressure.',
    st: 'RPG L99, Shooter L99, and Crawler use the same release checklist pattern. The items differ slightly by genre, but the discipline is identical: systematic verification before shipping.' },
  { file: 'lesson-platformer-100-ship-export-ready.ts',
    bt: '**Shipping without testing on a clean machine.** "Works on my machine" is not shipping evidence. Build from a clean checkout, run on a machine without your dev environment, and verify the game starts and plays correctly.',
    ei: 'Valve tests every Steam release on standardized hardware profiles. The clean-room build test is the final quality gate. Your export-ready test follows the same principle: verify the build works outside your development environment.',
    st: 'All four paths converge at Lesson 100: a standalone, shippable game ready for a portfolio. The final export is the culmination of 100 lessons of engineering discipline. Genre differences vanish at the shipping gate.' },

  // === ST only (already have BT and EI) ===
  { file: 'lesson-platformer-21-deterministic-rng-v0.ts',
    st: 'The RPG seeds its RNG identically (L21) to guarantee combat outcomes match between recording and playback. The Shooter seeds per-wave for enemy spawn patterns. Deterministic RNG is a cross-path requirement — replay and save/load both depend on reproducible random sequences.' },

  // === EI, ST (already have BT) ===
  { file: 'lesson-platformer-22-no-rand-rule.ts',
    ei: 'Hades uses a single RNG stream for all gameplay randomness — loot, enemy behavior, room layout — seeded at the start of each run. One source means one seed reproduces the entire run. Your no-rand rule enforces the same single-source discipline.',
    st: 'The RPG enforces the same no-rand rule (L22). The Shooter channels all randomness through a seeded generator. Every path converges on the same constraint: rand() and random() are banned, only the seeded RNG is allowed.' },
  { file: 'lesson-platformer-23-state-signature-v0.ts',
    ei: 'Age of Empires computes a per-frame hash of all game state to detect multiplayer desync. Your state signature serves the same purpose for single-player replay verification — hash the observable state, compare between recording and playback.',
    st: 'RPG L23 and Shooter L68 compute state signatures. The Crawler computes floor-level hashes. The hash function and included fields differ by genre, but the purpose is identical: detect state divergence between two runs with the same input.' },

  // === BT, ST (already have EI) ===
  { file: 'lesson-platformer-31-input-module-split.ts',
    bt: '**Reading IsKeyDown in multiple systems.** If physics reads LEFT and collision reads LEFT independently, you get inconsistent behavior when both run in the same frame. Read input once into a snapshot struct, pass it to all systems.',
    st: 'RPG L31 and Shooter L31 split input the same way. The Crawler records raw input for replays. Input isolation is the first module split in every path — it sets the pattern for all subsequent system extractions.' },
  { file: 'lesson-platformer-36-fixed-timestep-accumulator.ts',
    bt: '**Using GetFrameTime() directly for physics calculations.** Variable frame delta means physics runs differently on 30fps and 144fps monitors. A fixed timestep accumulator runs physics at a constant rate (e.g., 1/60s) regardless of frame rate, consuming accumulated time in fixed-size bites.',
    st: 'The Shooter does not implement fixed timestep (entity movement is simpler). The RPG is turn-based (no physics timing). Fixed timestep is most critical in platformers where gravity, jump arcs, and collision resolution must be frame-rate independent.' },
  { file: 'lesson-platformer-38-moving-platforms.ts',
    bt: '**Moving the platform without carrying the player.** If the player stands on a moving platform and only the platform moves, the player slides off. Apply the platform velocity to the player when they are standing on it: player.x += platform.velocity.x.',
    st: 'The Shooter has no platforms. The RPG has no moving terrain. Moving platforms with rider attachment are unique to platformers, but the concept of relative motion (child inherits parent velocity) appears in any game with hierarchical movement.' },
  { file: 'lesson-platformer-39-error-handling.ts',
    bt: '**Silently ignoring invalid tile indices.** If a physics calculation produces an out-of-bounds grid index, returning 0 (empty) silently hides the bug. Log a warning with the invalid coordinates so you can trace and fix the root cause.',
    st: 'RPG L88 and Shooter L39 handle errors at the same boundaries. Every path validates the same entry points: array indices, pool access, file I/O. Defensive error handling at system boundaries is a universal robustness pattern.' },
  { file: 'lesson-platformer-40-robust-physics-gate.ts',
    bt: '**Declaring physics "robust" without edge-case testing.** Test: maximum velocity, zero-size entities, negative positions, simultaneous collisions from two directions. If any edge case crashes or produces wrong results, the physics is not robust.',
    st: 'RPG L40 and Shooter L40 validate similar modularity milestones. The gate criteria differ by genre, but the principle is identical: prove that your core systems handle edge cases gracefully before building more complexity on top.' },
  { file: 'lesson-platformer-41-dash-mechanic.ts',
    bt: '**Allowing the player to dash while already dashing.** If dash stacks, the player moves at infinite speed. Use a state flag: set dashing = true on activation, ignore new dash input until the dash completes and the cooldown expires.',
    st: 'The Shooter has no dash (ships move freely). The RPG has no real-time movement abilities. The Crawler uses WASD with no dash. Dash is uniquely platformer, but the state-machine pattern (idle > active > cooldown > idle) is universal for any timed ability.' },
  { file: 'lesson-platformer-43-wall-jump.ts',
    bt: '**Allowing wall jump without checking if the player is pressing away from the wall.** A wall jump should launch the player away from the wall. If you only check "touching wall + jump pressed," the player can wall-jump and immediately re-grab the same wall, climbing infinitely.',
    st: 'The Shooter has no walls. The RPG has grid walls but no jumping. The Crawler has 3D wall collision but no wall jumps. Wall jumping is uniquely platformer, but the concept of "contact + input direction = action" appears in melee combat and object interaction across all paths.' },
  { file: 'lesson-platformer-44-double-jump.ts',
    bt: '**Resetting the jump counter on wall jump.** If wall jump resets jumps_remaining to 2, the player has infinite jumps by alternating between wall jump and double jump. Only reset jumps_remaining when the player lands on a solid surface, not on wall contact.',
    st: 'The Shooter has no jump counter (free movement). The RPG is grid-based (no jumping). The Crawler uses 3D movement with no double jump. Jump counting is platformer-specific, but resource counters (ammo, charges, uses) that reset on specific events are universal.' },
  { file: 'lesson-platformer-45-movement-toolkit-gate.ts',
    bt: '**Testing each movement ability in isolation only.** Dash + wall jump, double jump + dash, wall slide + wall jump into dash — ability combinations create emergent movement. Test every two-ability and three-ability combination to find interaction bugs.',
    st: 'The Shooter gates weapon systems. The RPG gates combat systems. Every path has an "ability toolkit" gate that proves all player abilities work individually and in combination. The abilities differ, the verification principle is identical.' },
  { file: 'lesson-platformer-48-stomp-kill.ts',
    bt: '**Checking only the player Y position without checking velocity direction.** A player moving upward through an enemy from below is not a stomp. Check that the player is falling (velocity.y > 0) AND the player bottom is above the enemy top. Both conditions are required.',
    st: 'The Shooter kills enemies with bullets (collision + deactivate). The RPG kills enemies with combat resolution. The Crawler uses melee attacks. Stomp is uniquely platformer, but the pattern of "specific collision condition triggers enemy defeat" is universal.' },
  { file: 'lesson-platformer-49-knockback.ts',
    bt: '**Applying knockback as a position offset instead of a velocity impulse.** Position teleporting ignores walls and other collision. Apply knockback as a velocity impulse and let the physics system resolve it naturally — the player slides along walls instead of teleporting through them.',
    st: 'The Shooter applies explosion pushback as velocity impulses. The RPG has no real-time knockback (turn-based). The Crawler applies 3D knockback vectors. Velocity-based impulses that respect collision are the correct knockback implementation across all real-time paths.' },
  { file: 'lesson-platformer-50-midgame-slice-gate.ts',
    bt: '**Treating the midgame slice as "half done."** This gate is a vertical slice — every system works, even if content is minimal. Movement, combat, collectibles, HUD, and level transitions must all function together as an integrated whole.',
    st: 'RPG L50, Shooter L50, and Crawler L50 all hit the same midgame gate. The vertical slice proves architecture completeness — genre-specific features are built, connected, and tested before the second half of development.' },
];

function findPart1InstructionsEnd(content) {
  const part1Idx = content.indexOf('part1:');
  if (part1Idx === -1) return -1;
  const marker = 'instructions: `';
  const instrStart = content.indexOf(marker, part1Idx);
  if (instrStart === -1) return -1;
  const openTick = instrStart + marker.length;
  let closeTick = openTick;
  while (closeTick < content.length) {
    if (content[closeTick] === '`' && content[closeTick - 1] !== '\\') break;
    closeTick++;
  }
  return closeTick;
}

let modified = 0, skipped = 0, errors = 0;
for (const lesson of lessons) {
  const filePath = path.join(dir, lesson.file);
  if (!fs.existsSync(filePath)) { console.log('ERROR (not found): ' + lesson.file); errors++; continue; }
  let content = fs.readFileSync(filePath, 'utf8');
  const insertPos = findPart1InstructionsEnd(content);
  if (insertPos === -1) { console.log('ERROR (no part1 instructions): ' + lesson.file); errors++; continue; }
  const part1Start = content.indexOf('part1:');
  const existing = content.substring(part1Start, insertPos);
  const hasBT = /beginner trap|common mistake/i.test(existing);
  const hasEI = /elite insight|pro insight/i.test(existing);
  const hasST = /systems thinking|cross-path/i.test(existing);
  let sections = '';
  if (!hasBT && lesson.bt) sections += '\n\n## Beginner Trap\n' + lesson.bt;
  if (!hasEI && lesson.ei) sections += '\n\n## Elite Insight\n' + lesson.ei;
  if (!hasST && lesson.st) sections += '\n\n## Systems Thinking Connection\n' + lesson.st;
  if (sections === '') { console.log('SKIP (all present): ' + lesson.file); skipped++; continue; }
  content = content.substring(0, insertPos) + sections + content.substring(insertPos);
  fs.writeFileSync(filePath, content, 'utf8');
  modified++;
  const part1Section = content.substring(content.indexOf('part1:'), content.indexOf('part2:'));
  const instrBackticks = (part1Section.match(/(?<!\\)`/g) || []).length;
  if (instrBackticks % 2 !== 0) console.log('WARNING (odd backticks): ' + lesson.file);
  else console.log('OK: ' + lesson.file);
}
console.log('\n=== SUMMARY ===');
console.log('Modified: ' + modified + '  Skipped: ' + skipped + '  Errors: ' + errors + '  Total: ' + lessons.length);
